import heapq
G = {"s": [("a", 2), ("b", 5)], "a": [("t", 4)], "b": [("t", 1)]}
H = {"s": 3, "a": 2, "b": 1, "t": 0}
open_ = [(H["s"], 0, "s", [])]
while open_:
    f, g, n, path = heapq.heappop(open_)
    path = path + [n]
    if n == "t":
        print("optimal route:", "->".join(path), "cost=", g); break
    for m, c in G[n]:
        heapq.heappush(open_, (g + c + H[m], g + c, m, path))

