plan = ["s", "a", "t"]
dead = {"a"}
pos = "s"
while pos != "t":
    nxt = plan[plan.index(pos) + 1]
    if nxt in dead:
        print("hop to %s failed -> replanning around it" % nxt)
        plan = ["s", "b", "t"]; continue
    pos = nxt
print("arrived via:", "->".join(plan))

